#!/usr/bin/env python3
"""Build review manifest for source-checked 3000 BCE reference notes."""
import json
from pathlib import Path
R=Path(__file__).resolve().parent
wiki=lambda t,r:f'https://en.wikipedia.org/w/index.php?title={t}&oldid={r}'
P='events_wikipedia.json.gz';Q='events_wikipedia_regional.json.gz'
def event(id,name,lat,lon,radius,confidence,sources,note,regional=False):
 return {'pack':Q if regional else P,'event':{'id':id,'name':'c. 3000 BC: '+name,'start':-3000,'end':-2999,'lat':lat,'lon':lon,'radiusKm':radius,'kind':'cultural','effect':'note','confidence':confidence,'r2SourceEvidence':{'sources':sources,'review_note':note,'date_precision':'Approximate archaeological context; 3000 BCE is a gameplay reference, not a verified exact date.','location_precision':('Regional reference point and gameplay radius; not the culture or settlement boundary.' if regional else 'Archaeological site coordinates; radius is a gameplay setting, not a mapped site boundary.'),'reviewed_as_of':'2026-10-28'}}}
events=[
 event('r2_harappa_ravi_c3000','Harappa is inhabited during the early Ravi phase',30.62889,72.86389,20,'wikipedia_coord',[wiki('Harappa',1382238880),'https://whc.unesco.org/en/tentativelists/1878/','https://www.harappa.com/category/slide-subject/ravi-phase'],'The archaeological Ravi phase is approximately 3300–2800 BCE; the later mature city dates approximately 2600–1900 BCE. This note describes early settlement, not the founding date or mature city.'),
 event('r2_dholavira_early_c3000','early settlement at Dholavira, in present-day Gujarat',23.88861,70.21364,20,'wikipedia_coord',[wiki('Dholavira',1380144703),'https://whc.unesco.org/en/list/1645/','https://whc.unesco.org/document/189324'],'UNESCO places earliest evidence around 3000 BCE. Wikipedia gives conflicting stage dates, including a 2650 BCE infobox and research that dates the first stages earlier; the precise onset is debated. The later walled city and reservoirs are not asserted for this reference year.'),
 event('r2_shahr_sukhteh_c3000','Shahr-e Sukhteh is inhabited in southeastern Iran',30.59528,61.32639,20,'wikipedia_coord',[wiki('Shahr-e_Sukhteh',1379197586),'https://whc.unesco.org/en/list/1456/','https://www.iranicaonline.org/articles/italy-vi-italian-excavations-in-iran-2/'],'Wikipedia and UNESCO differ on occupation endpoints but both support habitation around 3000 BCE. The Wikipedia article dates an end-of-phase fire around 3000 BCE, but its cited Encyclopaedia Iranica places that fire around 2700 BCE; no fire or exact-year founding is asserted.'),
 event('r2_supe_valley_c3000','settlements exist in Peru’s Supe Valley, where Caral later becomes a major center',-10.89361,-77.52028,80,'wikipedia_region',[wiki('Norte_Chico_civilization',1375529882),wiki('Caral',1379214244),'https://whc.unesco.org/document/152221','https://whc.unesco.org/en/list/1269/'],'ICOMOS states Supe Valley settlements were occupied in 3000 BCE and distinguishes the organized capital zone around 2600 BCE. Wikipedia dates Caral itself approximately 2600–2000 BCE, while UNESCO uses 3000–1800 BCE for the site; therefore this note concerns the valley, not an exact 3000 BCE date for the city. The later Caral site is only a regional reference point.',True),
 event('r2_valdivia_coast_c3000','Valdivia culture is present on the coast of present-day Ecuador',-2.36528,-80.65361,100,'wikipedia_region',[wiki('Valdivia_culture',1343001907),'https://www.metmuseum.org/toah/ht/02/sa','https://www.metmuseum.org/essays/real-alto','https://en.wikipedia.org/wiki/Real_Alto'],'The Metropolitan Museum places Valdivia culture around 3300–1500 BCE. The coordinate is an approximate regional anchor at the archaeological site of Real Alto; it is not a claim that the settlement had any particular later layout in 3000 BCE. The radius is a gameplay setting and does not cover or define all Valdivia sites.',True),
]
(R/'reviews/3000_bce_world_2026-10.json').write_text(json.dumps({'schema':'eternal-r2-3000bce-world-v1','additions':events},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
